base={'sword':100.0,'amulet':60.0,'staff':80.0,'potion':40.0}
comp=25.0
import itertools
def premium_before_fee(items, years=0, prev=0):
    mains=[i for i in items if i[0] in base]
    comps=[i for i in items if i[0] not in base]
    from collections import Counter
    c=Counter(k for k,_,_ in comps)
    b=sum(base[k] for k,_,_ in mains)+sum(60.0 if n==3 else n*comp for n in c.values())
    im=0.0
    for k,cu,en in items:
        ib=base[k] if k in base else comp
        r=(0.5 if cu else 0)+(0.3 if en>=5 else 0)
        im+=ib*r
    rate=0.10+(-0.20 if years>=2 else 0)+(-0.15 if prev>0 else 0)
    return b+b*rate+im
# search small policies
kinds=list(base)+['rune']
found=[]
