//! The ceiling the MHPCO puts on what a policy will ever pay out.
//!
//! This is the office's exposure limit. It changes when the MHPCO revises how
//! far it will stand behind a policy -- a different multiple of the insurance
//! sum, a different basis for that sum, a cap carried across successive claims
//! -- independently of the clauses that judge any single damage, and
//! independently of how the premium side surcharged the same items: premium
//! modifiers never raise the cap.

use crate::pricing::insurance_sum;
use crate::{Item, Settlement};

/// The total payout per policy is capped at twice its insurance sum.
const CAP_MULTIPLE: i64 = 2;

/// The most the office will ever pay out on a policy covering these items.
fn policy_cap(items: &[Item]) -> i64 {
    CAP_MULTIPLE * insurance_sum(items)
}

/// What the office actually settles once its exposure limit is applied to the
/// amount the claim's clauses would otherwise pay. The MHPCO does not refuse a
/// claim that outruns the cap; it pays up to the ceiling and reports how much
/// of the policy's exposure is left.
pub(crate) fn settle_within_cap(items: &[Item], desired_payout: i64) -> Settlement {
    let cap = policy_cap(items);
    let payout = desired_payout.min(cap);
    Settlement {
        payout,
        remaining_cap: cap - payout,
    }
}
=== LIB ===
pub struct Damage {
    pub item_type: String,
    pub amount: i64,
}

pub struct Settlement {
    pub payout: i64,
    pub remaining_cap: i64,
}

pub struct Policy<'a> {
    insured: &'a [Item],
}

impl<'a> Policy<'a> {
    pub fn insuring(items: &'a [Item]) -> Self {
        Policy { insured: items }
    }

    /// A settlement totals what the office reimburses for each damage the
    /// incident reported.
    pub fn claim(&self, damages: &[Damage]) -> Settlement {
        let reimbursed: f64 = damages
            .iter()
            .map(|damage| damage_reimbursement(damage, matched_cover(self.insured, damage)))
            .sum();
        settle_within_cap(self.insured, round_payout_in_mhpco_favor(reimbursed))
    }
}

/// A premium is rounded in the MHPCO's favor, which for money the customer
/// owes the office means upwards.
fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
    premium.ceil() as i64
}

/// A payout is rounded in the MHPCO's favor, which for money the office owes
/// the claimant means downwards. Only the settlement total is rounded; the
/// reimbursements it sums are carried as fractions.
fn round_payout_in_mhpco_favor(payout: f64) -> i64 {
    payout.floor() as i64
}

